def _tp_from_cache(session):
    """Close out condors whose profit-target order filled, from the broker's local fill cache."""
    filled = {f.order_id for f in broker.cached_fills()}
    done = []
    for c in session.query(Condor).filter(Condor.expiry == et_today(), Condor.status == "open"):
        if c.pt_order_id in filled:
            c.close(debit=c.pt_limit, why="profit_target")
            done.append(c)
    session.commit()
    return done
